must have curve sections

    
        Andromeda Cube 
        Andromeda Cube 
        David Pitcher
        Boris
        2017-08-23
        https://twistypuzzles.com/app/museum/museum_showitem.php?pkey=2553
        http://twistypuzzles.com/forum/viewtopic.php?f=15&t=22276
        https://www.youtube.com/watch?v=839fqQCWFZo
    

    
        K  := 0.5;

        K1 := (6 * (9 + sqrt(33)))^(1/3);
        K2 := (6 * (9 - sqrt(33)))^(1/3);
        K3 := (2 * (1777 + 33*sqrt(33)))^(1/3);
        K4 := (2 * (1777 - 33*sqrt(33)))^(1/3);

        C0 := K * sqrt(6 * (-6 + K1 + K2)) / 12;
        C1 := K * sqrt(6 * ( 6 + K1 + K2)) / 12;
        C2 := K * sqrt(6 * (18 + K1 + K2)) / 12;
        C3 := K * sqrt(6 * (14 + K3 + K4)) / 12;

        n1 := (c1 - c0)^2;
        n2 := (c1 - c2)^2;
        n3 := (c1 - c2) * (c0 - c1);

        bgx := -n2*n3 + n1^2;
        bgy :=  n1*n2 - n3^2;
        bgz := -n1*n3 + n2^2;

        byx := -n2^2 + n1*n3;
        byy :=  n1^2 - n2*n3;
        byz := -n3^2 + n1*n2;

        A1 := ArcCos((bgx*byx + bgy*byy + bgz*byz) / (bgx^2 + bgy^2 + bgz^2));
        A2 := 2 * Pi - 4 * A1;
        A3 := 2 * A1;
        A4 := 3 * A1;

        D  := 0.47;
